void parallelForces(Particle *particles, const size_t particleCount, const size_t start, const size_t end, const uint32_t *particleTable, float mass, float viscosity, float spikyGrad, float spikyLap, float h, float h2) {
    const float PI = 3.14159265f;
    const float h6 = h2 * h2 * h2;
    const float mass2 = mass * mass;

    for (size_t particleIndex = start; particleIndex < end; particleIndex++) {
        Particle &particle = particles[particleIndex];
        glm::vec3 force = glm::vec3(0.0f);

        // Get cell of current particle
        glm::ivec3 cell = glm::ivec3(glm::floor(particle.position / h));

        // Check all 27 neighboring cells
        for (int i = -1; i <= 1; i++) {
            for (int j = -1; j <= 1; j++) {
                for (int k = -1; k <= 1; k++) {
                    glm::ivec3 neighborCell = cell + glm::ivec3(i, j, k);
                    uint32_t hash = getHash(neighborCell);
                    uint32_t idx = particleTable[hash % TABLE_SIZE];

                    // Traverse collision chain
                    while (idx != NO_PARTICLE && idx < particleCount) {
                        Particle &neighbor = particles[idx];

                        // Skip self
                        if (idx != particleIndex) {
                            glm::vec3 diff = neighbor.position - particle.position;
                            float dist = glm::length(diff);

                            if (dist < h && dist > 0.0001f) {
                                // Pressure force (spiky kernel gradient)
                                float diffDist = h - dist;
                                float pressureScalar = spikyGrad * diffDist * diffDist / dist;
                                float pressureTerm = -mass * (particle.pressure + neighbor.pressure) / (2.0f * neighbor.density);
                                force += pressureTerm * pressureScalar * diff;

                                // Viscosity force (viscosity kernel Laplacian)
                                float viscosityTerm = viscosity * mass * (neighbor.density - particle.density) / (h2 * neighbor.density * dist);
                                float lapScalar = spikyLap * diffDist;
                                force += viscosityTerm * lapScalar * diff;
                            }
                        }
                        idx++;
                    }
                }
            }
        }

        particle.force = force;
    }
}

